// Cloudflare Worker entry: serves the Next.js app (built by OpenNext) and runs
// the daily pledge-reminder job on the cron schedule in wrangler.jsonc.
// Generated by `opennextjs-cloudflare build` (worker.ts is excluded from tsc).
import { default as handler } from "./.open-next/worker.js";

type Env = { APP_URL?: string; CRON_SECRET?: string };

const worker = {
  fetch: handler.fetch,

  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const base = env.APP_URL || "https://localhost";
    const req = new Request(`${base}/api/cron/reminders`, {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
    });
    ctx.waitUntil(
      handler.fetch(req, env, ctx).then(async (res: Response) => {
        console.log("pledge reminders:", res.status, await res.text());
      }),
    );
  },
};

export default worker;
